import { ChainDataError, compareLogs, logKey, contractInterface, wordHex, checkAbort, decodeLog } from './client.js';
import { cachedEvents, cachedLogs, previousEvents, readArtifact, writeArtifact } from './event-store.js';
import { decodeEntryReveal, decodeTicketBatchReveal, decodeBaseKey, deriveTraits, deriveFoil, isFoil, ticketStreamReplay } from './traits.js';
import { playerAddress, uint } from './state.js';
import { hasTicketBatches } from './schema.js';

export async function generationWindow(s, level) {
  const [start, next] = await Promise.all([
    s.field('GAME', 'ticketGenerationStartBlock', level),
    level <= 0xfffffd ? s.field('GAME', 'ticketGenerationStartBlock', level + 2) : 0n,
  ]);
  // Since audit 26ad5863 future levels are no longer minted ahead: level L's window is stamped at
  // the seal of purchase level L - 1 (AdvanceModule._sealPurchaseDay / the turbo arm), and its
  // tickets can still mint through L's own jackpot phase, which ends before L + 2 is stamped.
  if (!start) return null;
  // The promotion transaction may finish old-level work before stamping the
  // next window. Include its whole block and filter the level from each event.
  return { fromBlock: Number(start), toBlock: next ? Number(next) : s.block.number };
}

async function receiptEvents(client, hash, signal, blockHash) {
  const iface = await contractInterface('GAME'); const receipt = await client.receipt(hash, signal, blockHash);
  return receipt.logs.filter(log => log.address.toLowerCase() === client.address('GAME')).flatMap(log => {
    let parsed; try { parsed = decodeLog(iface, log); } catch { return []; }
    return parsed ? [{ ...log, name: parsed.name, args: parsed.args }] : [];
  });
}
async function priorWord(s, event, events, kind, signal, windowAnchors) {
  const name = kind.startsWith('lootbox') ? 'LootboxRngApplied' : 'DailyRngApplied';
  let candidates = events.filter(row => row.name === name && compareLogs(row, event) < 0);
  if (!candidates.length && windowAnchors) {
    // ⛔ Anchors inside the generation window come from ONE cached query per level, not a backward
    // scan per ticket batch (measured 54 scans on a whale's cold load). The whole block of a found
    // anchor lies inside the window, so every anchor of its transaction is present too.
    const before = (await windowAnchors(name)).filter(row => compareLogs(row, event) < 0);
    if (before.length) candidates = before.filter(row => row.transactionHash === before.at(-1).transactionHash);
  }
  if (!candidates.length) {
    const previous = await previousEvents(s.client, 'GAME', name, event, { signal });
    if (!previous.length) throw new ChainDataError(`Missing ${name} anchor for ticket generation.`, 'INCOMPLETE_HISTORY');
    // A large backfill can span the first block in a page. Read the entire
    // transaction, then choose the greatest lootbox index, not the last log.
    candidates = kind === 'lootbox-cohort' ? previous
      : (await receiptEvents(s.client, previous.at(-1).transactionHash, signal, previous.at(-1).blockHash)).filter(row => row.name === name && compareLogs(row, event) < 0);
  }
  // Modern cohort indices are recycled 0/1 buffers, so event order, not the
  // greatest numeric index, identifies the committed word for this stream.
  if (kind === 'lootbox-cohort') return candidates.at(-1).args.word;
  if (kind === 'lootbox') return candidates.reduce((a, b) => BigInt(a.args.index) > BigInt(b.args.index) ? a : b).args.word;
  // Current contracts skip gap days after applying them and apply the actual
  // settlement word last. Counting seals fails because skipped days never seal.
  return candidates.at(-1).args.finalWord;
}
async function batchTraits(baseKey, startIndex, count, entropy, signal) {
  checkAbort(signal);
  if (count >= 1024 && typeof Worker !== 'undefined') {
    return new Promise((resolve, reject) => {
      const worker = new Worker(new URL('./traits-worker.js', import.meta.url), { type: 'module' });
      const finish = (error, value) => { worker.terminate(); signal?.removeEventListener('abort', abort); error ? reject(error) : resolve(value); };
      const abort = () => finish(signal.reason ?? new DOMException('Read cancelled', 'AbortError'));
      signal?.addEventListener('abort', abort, { once: true });
      worker.onmessage = ({ data }) => finish(data.error ? new ChainDataError(data.error) : null, data.traits);
      worker.onerror = event => finish(new ChainDataError(event.message || 'Trait worker failed.'));
      worker.postMessage({ baseKey: String(baseKey), startIndex, count, entropy: String(entropy) });
    });
  }
  // Small batches stay below a frame budget. Splits must occur at LCG group
  // boundaries, because its offset shortcut is not a sequential skip-ahead.
  const result = new Uint8Array(count); let offset = 0;
  const stream = ticketStreamReplay(baseKey);
  const replayState = stream ? { goldSixTaken: stream.goldSixTaken } : null;
  while (offset < count) {
    checkAbort(signal);
    const size = Math.min(count - offset, 256 - ((startIndex + offset) & 15));
    result.set(deriveTraits(baseKey, startIndex + offset, size, entropy, replayState), offset); offset += size;
    if (offset < count) await new Promise(resolve => setTimeout(resolve, 0));
  }
  return result;
}

export async function revealedEntries(s, rawPlayer, rawLevel, { signal } = {}) {
  const player = playerAddress(rawPlayer); const level = uint(rawLevel); const window = await generationWindow(s, level);
  if (!window) return [];
  const key = wordHex((BigInt(level) << 160n) | BigInt(player));
  const [positions, legacy] = await Promise.all([
    Promise.all([0, 1, 2, 3].map(position => cachedLogs(s, { address: s.client.address('GAME'), topics: Array.from({ length: position + 1 }, (_, i) => i === position ? key : null) }, { ...window, signal }))),
    cachedEvents(s, 'GAME', 'TraitsGenerated', { player }, { ...window, signal }),
  ]);
  const seated = [...new Map(positions.flat().map(log => [logKey(log), log])).values()];
  const batches = seated.map(log => ({ ...log, traits: decodeEntryReveal(log, level, player), source: 'seated' }));
  // Audit 95d88f68b: a main-daily ticket win can be written straight into this (live) level and
  // revealed in JackpotTicketBatchTraits by owner registry index, so it never queues or seats.
  if (await hasTicketBatches()) {
    const ownerId = Number(await s.field('GAME', 'ticketOwnerId', player));
    if (ownerId) {
      for (const log of await cachedEvents(s, 'GAME', 'JackpotTicketBatchTraits', { lvl: level }, { ...window, signal })) {
        const traits = decodeTicketBatchReveal(log.args, ownerId - 1);
        if (traits.length) batches.push({ ...log, traits, source: 'jackpot' });
      }
    }
  }
  const rows = legacy.filter(log => decodeBaseKey(log.args.baseKey).level === level);
  const receipts = new Map(); const words = new Map(); const anchors = new Map();
  const windowAnchors = name => {
    if (!anchors.has(name)) anchors.set(name, cachedEvents(s, 'GAME', name, {}, { ...window, signal }));
    return anchors.get(name);
  };
  // Sequential bounded work avoids launching one RPC/worker per purchased
  // ticket. Receipt and entropy anchors are shared by all slices in a drain.
  for (const row of rows) {
    checkAbort(signal); const { baseKey, take } = row.args;
    const stream = ticketStreamReplay(baseKey);
    const artifactKey = `${s.client.chain.id}:${s.client.address('GAME')}:${row.blockHash}:${logKey(row)}${stream ? ':stream-v1' : ''}`;
    const saved = await readArtifact(artifactKey);
    if (saved) { batches.push({ ...row, traits: saved.traits, source: saved.source }); continue; }
    if (!stream && !receipts.has(row.transactionHash)) receipts.set(row.transactionHash, await receiptEvents(s.client, row.transactionHash, signal, row.blockHash));
    // Versioned streams carry their continuation offset directly. Their shared
    // RNG anchors suffice; do not download a receipt per generation batch.
    const events = stream ? [] : receipts.get(row.transactionHash); let traits;
    if (isFoil(baseKey, take)) {
      const record = await s.call('GAME_LENS', 'foilRecordOf', [s.client.address('GAME'), level, player]);
      if (!record.present) throw new ChainDataError('A generated foil pack has no on-chain record.', 'INCOMPLETE_HISTORY');
      if (stream) {
        if (!record.resolved || record.lines?.length !== 4) throw new ChainDataError('A generated foil pack has no resolved lines.', 'INCOMPLETE_HISTORY');
        traits = Array.from(record.lines).flatMap(line => [0n, 8n, 16n, 24n].map(shift => Number((BigInt(line) >> shift) & 255n)));
      } else {
        let entropy = await s.call('GAME', 'rngWordForDay', [record.resolveDay]);
        // Terminal fallback can drain an unworded foil day using rngWordCurrent.
        // The applied terminal word is emitted before those drains and persists
        // as an event even after _unlockRng restores the waiting sentinel.
        if (!entropy) entropy = await priorWord(s, row, events, 'daily', signal, windowAnchors);
        traits = deriveFoil({ buyer: player, level, entropy, multBps: record.multBps }).flat();
      }
    } else if (stream) {
      // Mine FLIP ticket work does not emit the legacy Advance(2/4/5) marker.
      // Its event carries the exact stream offset, replay flag and identity.
      const entropy = await priorWord(s, row, events, 'lootbox-cohort', signal, windowAnchors);
      traits = await batchTraits(baseKey, stream.offset, Number(take), entropy, signal);
    } else {
      const advances = events.filter(log => log.name === 'Advance');
      const stage = Number(advances[0]?.args.stage);
      if (advances.length !== 1 || ![2, 4, 5].includes(stage)) throw new ChainDataError('Unknown ticket generation stage.', 'INCOMPLETE_HISTORY');
      const wordKey = `${row.transactionHash}:${stage}`;
      if (!words.has(wordKey)) words.set(wordKey, await priorWord(s, row, events, stage === 5 ? 'lootbox' : 'daily', signal, windowAnchors));
      const decoded = decodeBaseKey(baseKey);
      const startIndex = events.filter(log => log.name === 'TraitsGenerated' && compareLogs(log, row) < 0 && log.args.player.toLowerCase() === player)
        .reduce((sum, log) => { const other = decodeBaseKey(log.args.baseKey); return sum + (other.level === level && other.queueIdx === decoded.queueIdx ? Number(log.args.take) : 0); }, 0);
      traits = await batchTraits(baseKey, startIndex, Number(take), words.get(wordKey), signal);
    }
    const derived = { traits: Array.from(traits), source: isFoil(baseKey, take) ? 'foil' : 'purchase' };
    writeArtifact(artifactKey, derived); batches.push({ ...row, ...derived });
  }
  return batches.sort(compareLogs);
}

export async function ticketInventory(s, player, level, options) {
  const [batches, owed] = await Promise.all([revealedEntries(s, player, level, options), s.call('GAME', 'entriesOwedView', [level, player])]);
  const queues = [[], [], [], []]; let entryId = 0;
  for (const batch of batches) for (const traitId of batch.traits) queues[traitId >> 6].push({ entryId: entryId++, traitId, traitLabel: null });
  const cards = Array.from({ length: Math.max(...queues.map(q => q.length)) }, (_, cardIndex) => {
    const entries = queues.map(q => q[cardIndex]).filter(Boolean);
    return { cardIndex, status: entries.length === 4 ? 'opened' : 'partial', entries, source: 'purchase', purchaseBlock: null };
  });
  return { address: player, level, day: null, totalEntries: entryId, pendingEntries: Number(owed), cards,
    presentationGrouping: true, blockNumber: String(s.block.number), blockHash: s.block.hash };
}

export async function foilInventory(s, player, level, { signal } = {}) {
  const record = await s.call('GAME_LENS', 'foilRecordOf', [s.client.address('GAME'), level, player]);
  if (!record.present) return { address: player, level, present: false, multBps: null, lines: null, claims: [] };
  const [batches, claims] = await Promise.all([
    revealedEntries(s, player, level, { signal }), cachedEvents(s, 'GAME', 'FoilMatchClaimed', { player }, { signal }),
  ]);
  const foil = batches.find(row => row.source === 'foil');
  // Run 56's FoilMatchClaimed names the set it matched; from run 57 (audit 9ee8986d) a day has one
  // board and the event has no drawKind, so every claim is the main draw (0).
  return { address: player, level, present: true, multBps: Number(record.multBps), resolveDay: Number(record.resolveDay),
    lines: foil ? [0, 1, 2, 3].map(i => foil.traits.slice(i * 4, i * 4 + 4)) : null,
    claims: claims.map(row => ({ day: Number(row.args.day), ticketIndex: Number(row.args.ticketIndex), drawKind: Number(row.args.drawKind ?? 0), tier: Number(row.args.tier) })) };
}

// Counts need neither receipt downloads nor trait hashing. Query all active
// levels in each anonymous topic position's OR list: four scans for the whole
// window, plus the normal player-indexed generation stream.
// `mintedThrough`: the highest level that CAN hold generated tickets (audit 26ad5863 mints at most
// the active level and the next, one more once the last purchase day latches). Levels above it have
// no generation window by construction, so their stamps are not read — they count owed entries only.
export async function ticketCounts(s, rawPlayer, levels, { signal, mintedThrough = null } = {}) {
  const player = playerAddress(rawPlayer);
  const windows = await Promise.all(levels.map(level => (
    mintedThrough != null && level > mintedThrough ? null : generationWindow(s, level))));
  const active = windows.map((window, i) => ({ window, level: levels[i] })).filter(row => row.window);
  const counts = new Map(levels.map(level => [level, 0]));
  if (active.length) {
    const fromBlock = Math.min(...active.map(row => row.window.fromBlock));
    const toBlock = Math.max(...active.map(row => row.window.toBlock));
    const topics = active.map(row => wordHex((BigInt(row.level) << 160n) | BigInt(player)));
    const [positions, normal] = await Promise.all([
      Promise.all([0,1,2,3].map(position => cachedLogs(s, { address: s.client.address('GAME'), topics: Array.from({length:position+1},(_,i)=>i===position?topics:null) }, { fromBlock, toBlock, signal }))),
      cachedEvents(s, 'GAME', 'TraitsGenerated', { player }, { fromBlock, toBlock, signal }),
    ]);
    const seated = [...new Map(positions.flat().map(log=>[logKey(log),log])).values()];
    for (const { level } of active) {
      for (const log of seated) counts.set(level, counts.get(level) + decodeEntryReveal(log, level, player).length);
    }
    for (const log of normal) { const { level } = decodeBaseKey(log.args.baseKey); if (counts.has(level)) counts.set(level, counts.get(level) + Number(log.args.take)); }
  }
  return Promise.all(levels.map(async level => {
    const generatedEntries = counts.get(level); const pendingEntries = Number(await s.call('GAME', 'entriesOwedView', [level,player]));
    return { level, entryCount: generatedEntries + pendingEntries, generatedEntries, pendingEntries };
  }));
}
